import React, { useState, useRef, useEffect } from 'react';
import { Send, Phone, Video, MoreVertical, Paperclip, Smile } from 'lucide-react';

const ChatWindow = ({ conversation, messages = [], loading, onSendMessage, onClose }) => {
  const [inputMessage, setInputMessage] = useState('');
  const [isSending, setIsSending] = useState(false);
  const messagesEndRef = useRef(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async () => {
    if (!inputMessage.trim() || !conversation) return;

    setIsSending(true);
    try {
      await onSendMessage(conversation.id, inputMessage);
      setInputMessage('');
    } catch (error) {
      console.error('Erreur:', error);
    } finally {
      setIsSending(false);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const userData = JSON.parse(localStorage.getItem('userData') || '{}');

  // Déterminer l'autre utilisateur
  const otherUser = userData.id === conversation?.user_id 
    ? { 
        name: `${conversation.admin_first_name} ${conversation.admin_last_name}`,
        role: 'admin'
      }
    : { 
        name: `${conversation.first_name} ${conversation.last_name}`,
        role: 'user'
      };

  return (
    <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-2xl border border-white/40 dark:border-neutral-800/60 h-[600px] flex flex-col overflow-hidden">
      {/* Header */}
      <div className="flex-shrink-0 p-6 border-b border-neutral-200/50 dark:border-neutral-800/50 flex items-center justify-between">
        <div className="flex items-center gap-3 flex-1">
          <div className="h-12 w-12 rounded-full bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center text-white font-bold text-lg">
            {otherUser.name?.charAt(0).toUpperCase()}
          </div>
          <div className="flex-1 min-w-0">
            <h3 className="font-semibold text-lg text-neutral-900 dark:text-white truncate">
              {otherUser.name}
            </h3>
            <div className="flex items-center gap-2">
              <div className="h-2 w-2 rounded-full bg-green-500 animate-pulse"></div>
              <p className="text-sm text-neutral-500">En ligne</p>
              {conversation?.status && (
                <span className={`px-2 py-0.5 text-xs rounded-full ${
                  conversation.status === 'open' ? 'bg-green-100 text-green-800' : 
                  conversation.status === 'pending' ? 'bg-yellow-100 text-yellow-800' : 
                  'bg-gray-100 text-gray-800'
                }`}>
                  {conversation.status === 'open' ? 'Ouverte' : 
                   conversation.status === 'pending' ? 'En attente' : 'Fermée'}
                </span>
              )}
            </div>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors">
            <Phone className="w-5 h-5 text-neutral-600 dark:text-neutral-400" />
          </button>
          <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors">
            <Video className="w-5 h-5 text-neutral-600 dark:text-neutral-400" />
          </button>
          <button onClick={onClose} className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors">
            <MoreVertical className="w-5 h-5 text-neutral-600 dark:text-neutral-400" />
          </button>
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-6 space-y-4">
        {loading ? (
          <div className="flex justify-center items-center h-full">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary-500"></div>
          </div>
        ) : messages.length === 0 ? (
          <div className="flex justify-center items-center h-full">
            <p className="text-neutral-500">Aucun message pour le moment</p>
          </div>
        ) : (
          messages.map((message) => {
            const isOwn = message.sender_id === userData.id;
            const messageTime = new Date(message.created_at);

            return (
              <div key={message.id} className={`flex ${isOwn ? 'justify-end' : 'justify-start'}`}>
                <div
                  className={`max-w-xs lg:max-w-md px-4 py-3 rounded-2xl ${
                    isOwn
                      ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-br-none'
                      : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-900 dark:text-white rounded-bl-none'
                  }`}
                >
                  {!isOwn && (
                    <div className="flex items-center gap-2 mb-1">
                      <span className="text-xs font-medium text-primary-600 dark:text-primary-400">
                        {message.sender?.first_name || 'Utilisateur'}
                      </span>
                    </div>
                  )}
                  <p className="text-sm break-words">{message.content}</p>
                  <div className={`flex items-center justify-between mt-2 ${isOwn ? 'text-white/70' : 'text-neutral-500'}`}>
                    <span className="text-xs">
                      {messageTime.toLocaleTimeString('fr-FR', {
                        hour: '2-digit',
                        minute: '2-digit'
                      })}
                    </span>
                    {isOwn && message.is_read && (
                      <span className="text-xs flex items-center gap-1">
                        <CheckCheck className="w-3 h-3" />
                        Lu
                      </span>
                    )}
                  </div>
                </div>
              </div>
            );
          })
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input */}
      <div className="flex-shrink-0 p-6 border-t border-neutral-200/50 dark:border-neutral-800/50">
        <div className="flex items-end gap-3">
          <button className="flex-shrink-0 p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors">
            <Paperclip className="w-5 h-5 text-neutral-600 dark:text-neutral-400" />
          </button>
          <button className="flex-shrink-0 p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors">
            <Smile className="w-5 h-5 text-neutral-600 dark:text-neutral-400" />
          </button>
          <div className="flex-1 relative">
            <textarea
              value={inputMessage}
              onChange={(e) => setInputMessage(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder="Écrivez votre message..."
              rows="1"
              className="w-full px-4 py-3 bg-neutral-100 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-2xl text-sm text-neutral-900 dark:text-white placeholder-neutral-500 focus:outline-none focus:ring-2 focus:ring-primary-500 resize-none"
            />
          </div>
          <button
            onClick={handleSend}
            disabled={isSending || !inputMessage.trim()}
            className="flex-shrink-0 p-3 bg-gradient-to-r from-primary-500 to-secondary-500 hover:from-primary-600 hover:to-secondary-600 disabled:opacity-50 text-white rounded-xl transition-all duration-200 hover:scale-105 active:scale-95"
          >
            <Send className="w-5 h-5" />
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatWindow;
